import{_ as e,o as t,c as o,a2 as l}from"./chunks/framework.mzJ8I8R4.js";const u=JSON.parse('{"title":"在本机使用","description":"","frontmatter":{},"headers":[],"relativePath":"guide/local.md","filePath":"guide/local.md"}'),r={name:"guide/local.md"};function i(n,a,p,d,s,c){return t(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="在本机使用" tabindex="-1">在本机使用 <a class="header-anchor" href="#在本机使用" aria-label="Permalink to &quot;在本机使用&quot;">​</a></h1><p>不部署服务器也能用：Android、macOS 和 Windows App 可以只在本机使用，不用注册账号，数据只存在这台设备上。</p><h2 id="和连接服务器的区别" tabindex="-1">和连接服务器的区别 <a class="header-anchor" href="#和连接服务器的区别" aria-label="Permalink to &quot;和连接服务器的区别&quot;">​</a></h2><ul><li><strong>不同步</strong>：每台设备的数据各自独立。要在多台设备之间同步，见<a href="./server">部署服务器</a>。</li><li><strong>没有网页版</strong>：网页版只能连接服务器。</li><li><strong>agent</strong>：只能在电脑上接入，见<a href="./agent#在本机使用时">接入 agent</a>。Android 上不能。</li><li><strong>AI 整理</strong>：配置只保存在这台设备上。</li><li><strong>更新</strong>：App 从 GitHub 获取新版本。</li></ul><p>其余功能完全一样。</p><h2 id="开始" tabindex="-1">开始 <a class="header-anchor" href="#开始" aria-label="Permalink to &quot;开始&quot;">​</a></h2><p>第一次打开 App 时选“在本机使用”即可。已经登录了服务器的，先在“设置”最下方退出登录，再在登录页选“在本机使用”。</p><h2 id="backup" tabindex="-1">备份 <a class="header-anchor" href="#backup" aria-label="Permalink to &quot;备份 {#backup}&quot;">​</a></h2><p>数据只在这台设备上，设备丢了或坏了，数据也就没了。请定期备份，把备份文件存到别处，比如网盘或另一台电脑。</p><ol><li>打开“设置”，在最上面的“本机模式”一组点“备份”。</li><li>选择保存的位置。备份文件名是 <code>NextTodo-备份-&lt;日期&gt;.db</code>。</li></ol><p>备份里有全部事项、文件夹、改动记录和令牌，不含 AI 整理的配置和 API 密钥。</p><h2 id="恢复" tabindex="-1">恢复 <a class="header-anchor" href="#恢复" aria-label="Permalink to &quot;恢复&quot;">​</a></h2><p>用备份替换这台设备上现在的全部数据：</p><ol><li>打开“设置”，在“本机模式”一组点“恢复”，选择备份文件。</li><li>确认替换。App 会重新启动，打开后就是备份时的数据。</li></ol><p>恢复前的数据不会删除，仍留在 App 的数据目录里。</p><p>换了新设备时，在新设备上选“在本机使用”，再恢复旧设备的备份，就能接着用。</p><p>App 无法启动时，页面上也有“恢复备份”按钮。</p><h2 id="改用服务器" tabindex="-1">改用服务器 <a class="header-anchor" href="#改用服务器" aria-label="Permalink to &quot;改用服务器&quot;">​</a></h2><p>在“设置 → 本机模式”里点“改用服务器”，App 会重新启动，回到登录页。本机的数据保留在这台设备上，以后再选“在本机使用”可以接着用，但不会自动搬到服务器上。</p>',19)])])}const _=e(r,[["render",i]]);export{u as __pageData,_ as default};
